package com.bank.backoff;

import java.util.*;
import java.util.logging.*;

public class PowersDemo {
    private static final Logger log = Logger.getLogger("Backoff");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        BackoffService service = new BackoffService();
        log.info(() -> "First 10 powers of 2 (backoff ms): " + service.powersOfTwo(10));
    }
}

// ─── Would be in service/BackoffService.java ───
class BackoffService {
    List<Long> powersOfTwo(int count) {
        return java.util.stream.Stream.iterate(1L, n -> n * 2)  // double each step
            .limit(count)                                        // bound infinite stream
            .toList();
    }
}
